 'By' => 'द्वारा',
 'By checking this option you will be able to provide service at customer location' => 'इस विकल्प को चेक करके आप ग्राहक के स्थान पर सेवा प्रदान कर सकेंगे',
 'By checking this option you will be able to provide service at your business location' => 'इस विकल्प को चेक करके आप अपने व्यावसायिक स्थान पर सेवा प्रदान कर सकेंगे',
 'By disabling Partial Payment, customers must pay the full bill using a single payment method.' => 'आंशिक भुगतान को अक्षम करके, ग्राहकों को एकल भुगतान विधि का उपयोग करके पूरे बिल का भुगतान करना होगा।',
 'By enabling Partial Payment, customers will be able to pay a portion of their bill using wallet balance and complete the remaining payment through the selected payment options.' => 'आंशिक भुगतान सक्षम करके, ग्राहक अपने बिल के एक हिस्से का भुगतान वॉलेट बैलेंस का उपयोग करके कर सकेंगे और शेष भुगतान चयनित भुगतान विकल्पों के माध्यम से पूरा कर सकेंगे।',
 'By enabling manual login, customers will get the option to create an account and log in using the necessary credentials & password in the app & website' => 'मैन्युअल लॉगिन सक्षम करने से, ग्राहकों को एक खाता बनाने और ऐप और वेबसाइट में आवश्यक क्रेडेंशियल और पासवर्ड का उपयोग करके लॉग इन करने का विकल्प मिलेगा।',
 'By providing valid SMTP credentials, the platform can deliver system notifications, OTPs, password reset emails, booking updates, and other automated messages.' => 'वैध एसएमटीपी क्रेडेंशियल प्रदान करके, प्लेटफ़ॉर्म सिस्टम नोटिफिकेशन, ओटीपी, पासवर्ड रीसेट ईमेल, बुकिंग अपडेट और अन्य स्वचालित संदेश वितरित कर सकता है।',
 'By selecting Cash After Service Will make it available as a payment option for customers during the checkout process' => 'कैश आफ्टर सर्विस का चयन करके इसे चेकआउट प्रक्रिया के दौरान ग्राहकों के लिए भुगतान विकल्प के रूप में उपलब्ध कराया जाएगा',
 'By selecting commission based business model provider can run business with you based on commission based payment per booking.' => 'कमीशन आधारित व्यवसाय मॉडल का चयन करके प्रदाता प्रति बुकिंग कमीशन आधारित भुगतान के आधार पर आपके साथ व्यवसाय चला सकता है।',
 'By selecting digital payment will make it available as a payment option for customers during the checkout process.' => 'डिजिटल भुगतान का चयन करने से यह चेकआउट प्रक्रिया के दौरान ग्राहकों के लिए भुगतान विकल्प के रूप में उपलब्ध हो जाएगा।',
 'By selecting instant booking, customers instantly book a service for a specific date without delays.' => 'तत्काल बुकिंग का चयन करके, ग्राहक बिना किसी देरी के तुरंत एक विशिष्ट तिथि के लिए सेवा बुक कर लेते हैं।',
 'By selecting offline payment will make it available as a payment option for customers during the checkout process.' => 'ऑफ़लाइन भुगतान का चयन करने से यह चेकआउट प्रक्रिया के दौरान ग्राहकों के लिए भुगतान विकल्प के रूप में उपलब्ध हो जाएगा।',
 'By selecting schedule booking, to book a service customers have to select specific date and time to book a service.' => 'किसी सेवा को बुक करने के लिए शेड्यूल बुकिंग का चयन करके ग्राहकों को सेवा बुक करने के लिए विशिष्ट तिथि और समय का चयन करना होगा।',
 'By selecting the subscription-based business model, provider can operate with you using a chosen subscription package.' => 'सदस्यता-आधारित व्यवसाय मॉडल का चयन करके, प्रदाता चुने हुए सदस्यता पैकेज का उपयोग करके आपके साथ काम कर सकता है।',
 'By switching this feature ON, Customer can pay with wallet balance & partially pay from other payment gateways.' => 'इस सुविधा को चालू करके, ग्राहक वॉलेट बैलेंस भुगतान कर सकता है और आंशिक रूप से अन्य भुगतान गेटवे भुगतान कर सकता है।',
 'By turning off availability mode, you will not get any new booking request from customers and customer will that you are currently unavailable to provide service' => 'उपलब्धता मोड को बंद करने से, आपको ग्राहकों से कोई नया बुकिंग अनुरोध नहीं मिलेगा और ग्राहक को पता चल जाएगा कि आप वर्तमान में सेवा प्रदान करने के लिए अनुपलब्ध हैं।',
 'By turning on maintenance mode Control your all system & function' => 'रखरखाव मोड चालू करके अपने सभी सिस्टम और फ़ंक्शन को नियंत्रित करें',
