 'How to Set Up & Use - choose the digital payment method you want to use, enter the required provider details (like API or merchant info), turn it on, and save to activate it for customers.' => 'सेट अप और उपयोग कैसे करें - वह डिजिटल भुगतान विधि चुनें जिसका आप उपयोग करना चाहते हैं, आवश्यक प्रदाता विवरण (जैसे एपीआई या व्यापारी जानकारी) दर्ज करें, इसे चालू करें, और ग्राहकों के लिए इसे सक्रिय करने के लिए सहेजें।',
