 'If Email verification is on, Customers must verify their Email with an verification code to complete the signup process.' => 'यदि ईमेल सत्यापन चालू है, तो ग्राहकों को साइनअप प्रक्रिया को पूरा करने के लिए सत्यापन कोड के साथ अपने ईमेल को सत्यापित करना होगा।',
 'If Phone Number verification is on, Customers must verify their Phone Number with an OTP to complete the signup process.' => 'यदि फ़ोन नंबर सत्यापन चालू है, तो ग्राहकों को साइनअप प्रक्रिया को पूरा करने के लिए एक ओटीपी के साथ अपने फ़ोन नंबर को सत्यापित करना होगा।',
 'If SMTP configuration is disabled or incorrect, the system will not be able to send any email notifications.' => 'यदि एसएमटीपी कॉन्फ़िगरेशन अक्षम या गलत है, तो सिस्टम कोई भी ईमेल सूचना नहीं भेज पाएगा।',
 'If disabled Subscription, All subscriber moved to commission and providers have to give a certain percentage of commission to admin for every booking request' => 'यदि सदस्यता अक्षम कर दी जाती है, तो सभी ग्राहक कमीशन में चले जाएंगे और प्रदाताओं को प्रत्येक बुकिंग अनुरोध के लिए व्यवस्थापक को कमीशन का एक निश्चित प्रतिशत देना होगा',
 'If disabled customers and provider will not receive notifications on their devices' => 'यदि अक्षम ग्राहक और प्रदाता अपने डिवाइस पर सूचनाएं प्राप्त नहीं करेंगे',
 'If disabled customers can not pay through this payment methods' => 'यदि विकलांग ग्राहक इस भुगतान विधियों के माध्यम भुगतान नहीं कर सकते हैं',
 'If enable this, newly uploaded/created files and data will store to 3rd party storage.' => 'यदि इसे सक्षम किया जाए, तो नई अपलोड की गई/निर्मित फ़ाइलें और डेटा तृतीय पक्ष संग्रहण में संग्रहीत हो जाएंगे।',
 'If enable this, newly uploaded/created files and data will store to local storage.' => 'यदि इसे सक्षम किया जाए, तो नई अपलोड की गई/निर्मित फ़ाइलें और डेटा स्थानीय संग्रहण में संग्रहीत हो जाएंगे।',
 'If enabled System will store all files and images to 3rd party storage' => 'सक्षम होने पर सिस्टम सभी फ़ाइलों और छवियों को तृतीय पक्ष संग्रहण में संग्रहीत करेगा',
 'If enabled System will store all files and images to local storage' => 'सक्षम होने पर सिस्टम सभी फ़ाइलों और छवियों को स्थानीय संग्रहण में संग्रहीत करेगा',
 'If enabled customers can only pay through this payment methods' => 'सक्षम होने पर ग्राहक केवल इस भुगतान विधियों के माध्यम भुगतान कर सकते हैं',
 'If enabled, Serviceman can cancel a booking request after it has been place' => 'यदि सक्षम किया गया है, तो सर्विसमैन बुकिंग अनुरोध होने के बाद उसे रद्द कर सकता है',
 'If enabled, Serviceman can edit a booking request after it has been place' => 'यदि सक्षम किया गया है, तो सर्विसमैन बुकिंग अनुरोध होने के बाद उसे संपादित कर सकता है',
 'If enabled, provider can delete account' => 'सक्षम होने पर, प्रदाता खाता हटा सकता है',
 'If enabled, providers can cancel a booking even after it has been placed.' => 'यदि सक्षम किया गया है, तो प्रदाता बुकिंग होने के बाद भी उसे रद्द कर सकते हैं।',
 'If enabled, providers can do self-registration from the admin landing page, provider panel & app, and customer website & app.' => 'सक्षम होने पर, प्रदाता व्यवस्थापक लैंडिंग पृष्ठ, प्रदाता पैनल और ऐप, और ग्राहक वेबसाइट और ऐप से स्व-पंजीकरण कर सकते हैं।',
 'If enabled, providers can edit a booking request after it has been placed' => 'यदि सक्षम किया गया है, तो प्रदाता बुकिंग अनुरोध रखे जाने के बाद उसे संपादित कर सकते हैं',
 'If enabled, providers can review reply' => 'सक्षम होने पर, प्रदाता उत्तर की समीक्षा कर सकते हैं',
 'If enabled, the provider will be automatically suspended by the system when their ‘Cash in Hand’ limit is exceeded.' => 'यदि सक्षम किया गया है, तो \'कैश इन हैंड\' सीमा पार होने पर प्रदाता को सिस्टम द्वारा स्वचालित रूप से निलंबित कर दिया जाएगा।',
 'If no access is selected, employees with this role can only view the section for which permissions are granted; they cannot perform any actions.' => 'यदि कोई पहुंच नहीं चुनी गई है, तो इस भूमिका वाले कर्मचारी केवल उस अनुभाग को देख सकते हैं जिसके लिए अनुमतियां दी गई हैं; वे कोई भी कार्य नहीं कर सकते।',
 'If the maximum limit is exceeded, the provider will be suspended and will not receive any service requests.' => 'यदि अधिकतम सीमा पार हो जाती है, तो प्रदाता को निलंबित कर दिया जाएगा और कोई सेवा अनुरोध प्राप्त नहीं होगा।',
 'If the required permissions are not in place, you’ll need to manually configure the cron job by adding the following command to your server’s crontab' => 'यदि आवश्यक अनुमतियाँ मौजूद नहीं हैं, तो आपको अपने सर्वर के क्रॉस्टैब में निम्न कमांड जोड़कर क्रॉन जॉब को मैन्युअल रूप से कॉन्फ़िगर करना होगा',
 'If there is any update available in the admin panel and the previous app will not work with it.' => 'यदि एडमिन पैनल में कोई अपडेट उपलब्ध है और पिछला ऐप उसके साथ काम नहीं करेगा।',
 'If this feature is active customers get the otp through firebase.' => 'यदि यह सुविधा सक्रिय है तो ग्राहकों को फायरबेस के माध्यम से ओटीपी मिलता है।',
 'If want to Update it for all upcoming bookings' => 'यदि आप इसे आगामी सभी बुकिंग के लिए अपडेट करना चाहते हैं',
 'If you activate reCAPTCHA, please ensure that reCAPTCHA v3 is properly set up beforehand.' => 'यदि आप reCAPTCHA सक्रिय करते हैं, तो कृपया सुनिश्चित करें कि reCAPTCHA v3 पहले से ठीक से सेट अप है।',
 'If you approve it, it will remain expired.' => 'यदि आप इसे स्वीकृत करते हैं, तो यह समाप्त हो जाएगा।',
 'If you are using a different path, find your mysqldump by running the command "which mysqldump" or "locate mysqldump" in your terminal, or ask your server provider.' => 'यदि आप किसी भिन्न पथ का उपयोग कर रहे हैं, तो अपने टर्मिनल में "who mysqldump" या "locate mysqldump" कमांड चलाकर अपना mysqldump ढूंढें, या अपने सर्वर प्रदाता से पूछें।',
 'If you cancel the subscription, after :countDays days the Provider will no longer be able to run the business before subscribe a new plan' => 'यदि आप सदस्यता रद्द करते हैं, तो :countDays दिनों के बाद प्रदाता नई योजना की सदस्यता लेने से पहले व्यवसाय नहीं चला पाएगा',
 'If you close now, the progress made so far will be saved.' => 'यदि आप अभी बंद करते हैं, तो अब तक की गई प्रगति बच जाएगी।',
 'If you close the tab, the progress made will be saved but remaining content will not be translated.' => 'यदि आप टैब बंद करते हैं, तो हुई प्रगति सहेज ली जाएगी लेकिन शेष सामग्री का अनुवाद नहीं किया जाएगा।',
 'If you do not have any project yet, create one with the website name.' => 'यदि आपके पास अभी तक कोई प्रोजेक्ट नहीं है, तो वेबसाइट नाम से एक प्रोजेक्ट बनाएं।',
 'If you do not need a force update, just insert zero (0) here and ignore it.' => 'यदि आपको फ़ोर्स अपडेट की आवश्यकता नहीं है, तो बस यहां शून्य (0) डालें और इसे अनदेखा करें।',
 'If you don’t have any project before. Create one with the website name' => 'अगर आपके पास पहले से कोई प्रोजेक्ट नहीं है. वेबसाइट नाम के साथ एक बनाएं',
 'If you have not created any project for your application yet, please create one first.' => 'यदि आपने अभी तक अपने एप्लिकेशन के लिए कोई प्रोजेक्ट नहीं बनाया है, तो कृपया पहले एक प्रोजेक्ट बनाएं।',
 'If you have questions or need assistance, contact our support team.' => 'यदि आपके कोई प्रश्न हैं या सहायता की आवश्यकता है, तो हमारी सहायता टीम से संपर्क करें।',
 'If you need assistance, contact our support team.' => 'यदि आपको सहायता की आवश्यकता है, तो हमारी सहायता टीम से संपर्क करें।',
 'If you select repeat booking, the customer can place the same service booking for multiple dates under one booking' => 'यदि आप दोबारा बुकिंग का चयन करते हैं, तो ग्राहक एक ही बुकिंग के तहत कई तिथियों के लिए एक ही सेवा बुकिंग कर सकता है',
 'If you switch this newly uploaded created files & data will store to 3rd party storage' => 'यदि आप इस नई अपलोड की गई फ़ाइलों को स्विच करते हैं और डेटा तृतीय पक्ष संग्रहण में संग्रहीत हो जाएगा',
 'If you switch this newly uploaded created files & data will store to local storage' => 'यदि आप इस नई अपलोड की गई फ़ाइलों को स्विच करते हैं और डेटा स्थानीय संग्रहण में संग्रहीत हो जाएगा',
 'If you turn of the availability status, this page will not show in the customer app and website' => 'यदि आप उपलब्धता स्थिति को चालू करते हैं, तो यह पृष्ठ ग्राहक ऐप और वेबसाइट पर दिखाई नहीं देगा',
 'If you turn off customer can`t pay through this payment gateway.' => 'यदि आप बंद कर देते हैं तो ग्राहक इस भुगतान गेटवे के माध्यम भुगतान नहीं कर सकता।',
 'If you turn off customer can`t pay through this payment geteway.' => 'यदि आप बंद कर देते हैं तो ग्राहक इस भुगतान गेटवे के माध्यम भुगतान नहीं कर सकता है।',
 'If you turn on The Status, this payment will show in dropdown list when withdraw request sent to admin.' => 'यदि आप स्टेटस चालू करते हैं, तो एडमिन को निकासी अनुरोध भेजे जाने पर यह भुगतान ड्रॉपडाउन सूची में दिखाई देगा।',
 'If you turn on the switch, this feature will be active and customers can make scheduled orders after the restriction time ends.' => 'यदि आप स्विच चालू करते हैं, तो यह सुविधा सक्रिय हो जाएगी और ग्राहक प्रतिबंध समय समाप्त होने के बाद निर्धारित ऑर्डर कर सकते हैं।',
 'If you want to use third-party storage, set up the connection with :third_party_storage_link.' => 'यदि आप तृतीय-पक्ष संग्रहण का उपयोग करना चाहते हैं, तो :third पार्टी संग्रहण लिंक के साथ कनेक्शन सेट करें।',
 'If you want, you can activate all 3 options based on your business need.' => 'आप चाहें तो अपनी व्यावसायिक आवश्यकता के आधार पर सभी 3 विकल्पों को सक्रिय कर सकते हैं।',
 'If your servers DUMP BINARY PATH does not match the following input field path, you must update it.' => 'यदि आपका सर्वर डंप बाइनरी पथ निम्नलिखित इनपुट फ़ील्ड पथ से मेल नहीं खाता है, तो आपको इसे अपडेट करना होगा।',
