 'In this page you can add, edit and status On/Off your business related pages.' => 'इस पृष्ठ में आप अपने व्यवसाय से संबंधित पृष्ठों को जोड़, संपादित और चालू/बंद कर सकते हैं।',
 'In this section, you can add offline payment methods to make them available as offline payment options for the customers' => 'इस अनुभाग में, आप ऑफ़लाइन भुगतान विधियों को ग्राहकों के लिए ऑफ़लाइन भुगतान विकल्प के रूप में उपलब्ध कराने के लिए जोड़ सकते हैं',
