 'Insert a valid phone number to get SMS' => 'एसएमएस प्राप्त करने के लिए एक वैध फ़ोन नंबर डालें',
 'Insert the wrong PHP file path - Copy the correct path and input it in the PHP file path Section' => 'गलत PHP फ़ाइल पथ डालें - सही पथ की प्रतिलिपि बनाएँ और इसे PHP फ़ाइल पथ अनुभाग में इनपुट करें',
 'Instagram' => 'Instagram',
 'Instant Booking' => 'तुरंत बुकिंग',
 'Instead of one-time payments, users remain active as long as their subscription is valid.' => 'एकमुश्त भुगतान के बजाय, उपयोगकर्ता तब तक सक्रिय रहते हैं जब तक उनकी सदस्यता वैध है।',
