 'Is Required' => 'आवश्यक है',
 'Is_Cancel' => 'रद्द है',
 'Is_Featured' => 'चित्रित है',
 'Is_Trail' => 'ट्रेल है',
 'It appears that you have not yet searched' => 'ऐसा प्रतीत होता है कि आपने अभी तक खोज नहीं की है',
 'It appears that you have not yet searched.' => 'ऐसा प्रतीत होता है कि आपने अभी तक खोज नहीं की है.',
 'It looks like your Apple ID Login configuration is not set up yet.' => 'ऐसा लगता है कि आपका Apple ID लॉगिन कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है।',
 'It looks like your Apple ID Login configuration is not set up yet. To enable the Apple ID Login option, please set up the Apple ID configuration first.' => 'ऐसा लगता है कि आपका Apple ID लॉगिन कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है। Apple ID लॉगिन विकल्प को सक्षम करने के लिए, कृपया पहले Apple ID कॉन्फ़िगरेशन सेट करें।',
 'It looks like your Apple configuration is not set up yet.' => 'ऐसा लगता है कि आपका Apple कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है।',
 'It looks like your Email configuration is not set up yet.' => 'ऐसा लगता है कि आपका ईमेल कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है।',
 'It looks like your Facebook Login configuration is not set up yet.' => 'ऐसा लगता है कि आपका फेसबुक लॉगिन कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है।',
 'It looks like your Facebook Login configuration is not set up yet. To enable the Facebook Login option, please set up the Facebook configuration first.' => 'ऐसा लगता है कि आपका फेसबुक लॉगिन कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है। फेसबुक लॉगिन विकल्प को सक्षम करने के लिए, कृपया पहले फेसबुक कॉन्फ़िगरेशन सेट करें।',
 'It looks like your Google configuration is not set up yet.' => 'ऐसा लगता है कि आपका Google कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है।',
 'It looks like your Google configuration is not set up yet. To enable the OTP system, please set up the Google configuration first.' => 'ऐसा लगता है कि आपका Google कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है। ओटीपी प्रणाली को सक्षम करने के लिए, कृपया पहले Google कॉन्फ़िगरेशन सेट करें।',
 'It looks like your SMS configuration is not set up yet.' => 'ऐसा लगता है कि आपका एसएमएस कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है।',
 'It looks like your server might not have the necessary permissions to automatically set up the cron job.' => 'ऐसा लगता है कि आपके सर्वर के पास क्रॉन जॉब को स्वचालित रूप से सेट करने के लिए आवश्यक अनुमतियाँ नहीं हैं।',
 'It looks like your social media configuration is not set up yet.' => 'ऐसा लगता है कि आपका सोशल मीडिया कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है।',
 'It must be greater then' => 'यह तो और भी बड़ा होना चाहिए',
 'It represents the brand and is usually displayed on the website or app header, login pages, invoices, and promotional materials.' => 'यह ब्रांड का प्रतिनिधित्व करता है और आमतौर पर वेबसाइट या ऐप हेडर, लॉगिन पेज, चालान और प्रचार सामग्री पर प्रदर्शित होता है।',
 'It usually includes the copyright symbol (©), the year, and your company name.' => 'इसमें आमतौर पर कॉपीराइट प्रतीक (©), वर्ष और आपकी कंपनी का नाम शामिल होता है।',
 'It will be downloaded as Zip format Filename.Zip.' => 'इसे ज़िप प्रारूप Filename.Zip के रूप में डाउनलोड किया जाएगा।',
