 'Once configured, use the Send Test Mail option to verify that emails are working correctly.' => 'एक बार कॉन्फ़िगर हो जाने पर, यह सत्यापित करने के लिए कि ईमेल सही ढंग से काम कर रहे हैं, टेस्ट मेल भेजें विकल्प का उपयोग करें।',
 'Once delete, you would not be translate this language' => 'एक बार डिलीट करने के बाद आप इस भाषा का अनुवाद नहीं कर पाएंगे',
 'Once deleted, it will no longer appear in the website footer.' => 'एक बार हटा दिए जाने के बाद, यह वेबसाइट फ़ुटर में दिखाई नहीं देगा।',
 'Once you ignore the request, it will be no longer on your booking request list.' => 'एक बार जब आप अनुरोध को अनदेखा कर देंगे, तो यह आपकी बुकिंग अनुरोध सूची में नहीं रहेगा।',
 'Once you turn off the Category Status, the Provider can’t subscribe to the services of that category and the Customer can’t find the category & its service when they want to book' => 'एक बार जब आप श्रेणी स्थिति को बंद कर देते हैं, तो प्रदाता उस श्रेणी की सेवाओं की सदस्यता नहीं ले सकता है और ग्राहक जब बुक करना चाहते हैं तो उन्हें श्रेणी और उसकी सेवा नहीं मिल पाती है।',
 'Once you turn off the Zone Status it will impact the category, services, and location finding for customers' => 'एक बार जब आप ज़ोन स्थिति को बंद कर देते हैं तो यह ग्राहकों के लिए श्रेणी, सेवाओं और स्थान खोजने को प्रभावित करेगा',
 'Once you turn off the page status, it will be hidden from users.' => 'एक बार जब आप पेज स्टेटस बंद कर देंगे, तो यह उपयोगकर्ताओं से छिपा रहेगा।',
 'Once you turn on the Category Status, the user can find the Category and its service for selection' => 'एक बार जब आप श्रेणी स्थिति चालू करते हैं, तो उपयोगकर्ता चयन के लिए श्रेणी और उसकी सेवा पा सकता है',
 'Once you turn on the Zone Status, the user can find the category, services, and location in that zone' => 'एक बार जब आप ज़ोन स्थिति चालू कर देते हैं, तो उपयोगकर्ता उस ज़ोन में श्रेणी, सेवाएँ और स्थान पा सकता है',
