 'The :firebase_configuration_link page must be configured for notifications to work.' => 'सूचनाओं के काम करने के लिए :firebase कॉन्फ़िगरेशन लिंक पृष्ठ को कॉन्फ़िगर किया जाना चाहिए।',
 'The Access Key ID is a publicly accessible identifier used to authenticate requests to S3.' => 'एक्सेस कुंजी आईडी एक सार्वजनिक रूप से सुलभ पहचानकर्ता है जिसका उपयोग S3 के अनुरोधों को प्रमाणित करने के लिए किया जाता है।',
 'The Admin Notification Setup for booking allows the administrator to configure how system notifications are sent and managed. Admin notifications can be delivered either manually or through Firebase, depending on the selected configuration' => 'बुकिंग के लिए व्यवस्थापक अधिसूचना सेटअप व्यवस्थापक को यह कॉन्फ़िगर करने की अनुमति देता है कि सिस्टम सूचनाएं कैसे भेजी और प्रबंधित की जाती हैं। चयनित कॉन्फ़िगरेशन के आधार पर व्यवस्थापक सूचनाएं या तो मैन्युअल रूप से या फ़ायरबेस के माध्यम से वितरित की जा सकती हैं',
 'The Business name often serves as the primary identifier for your business as a legal entity.' => 'व्यवसाय का नाम अक्सर कानूनी इकाई के रूप में आपके व्यवसाय के लिए प्राथमिक पहचानकर्ता के रूप में कार्य करता है।',
 'The Country Name field, when setting up a business is essential for a multitude of reasons, spanning legal, operational, financial, and marketing aspects.' => 'देश का नाम फ़ील्ड, व्यवसाय स्थापित करते समय कानूनी, परिचालन, वित्तीय और विपणन पहलुओं सहित कई कारणों से आवश्यक है।',
 'The Cron Job PHP configuration error occurs when' => 'क्रॉन जॉब PHP कॉन्फ़िगरेशन त्रुटि तब होती है जब',
 'The Customer will come to the your Location to receive the service' => 'ग्राहक सेवा प्राप्त करने के लिए आपके स्थान पर आएगा',
 'The PHP file path for a Cron Job refers to the location on the server where the PHP command to be executed is stored.' => 'क्रॉन जॉब के लिए PHP फ़ाइल पथ सर्वर पर उस स्थान को संदर्भित करता है जहां निष्पादित की जाने वाली PHP कमांड संग्रहीत है।',
 'The Service Location will be available after this booking accepts or assign to a provider' => 'इस बुकिंग को स्वीकार करने या प्रदाता को सौंपने के बाद सेवा स्थान उपलब्ध होगा',
 'The Service Location will be available after this booking assign to a provider' => 'इस बुकिंग के बाद सेवा स्थान एक प्रदाता को सौंपे जाने पर उपलब्ध होगा',
 'The ZipArchive class is not available' => 'ZipArchive वर्ग उपलब्ध नहीं है',
 'The Zone Selection field helps you select the specific locations from where you provide services.' => 'ज़ोन चयन फ़ील्ड आपको उन विशिष्ट स्थानों का चयन करने में मदद करता है जहाँ से आप सेवाएँ प्रदान करते हैं।',
 'The ad date has already expired.' => 'विज्ञापन की तारीख पहले ही समाप्त हो चुकी है.',
 'The aws region where your s3 bucket is hosted.' => 'AWS क्षेत्र जहां आपका s3 बकेट होस्ट किया गया है।',
 'The base url used to access your s3 bucket.' => 'आपके s3 बकेट तक पहुँचने के लिए उपयोग किया जाने वाला बेस यूआरएल।',
 'The command is not editable. Click copy button to copy the command' => 'आदेश संपादन योग्य नहीं है. कमांड को कॉपी करने के लिए कॉपी बटन पर क्लिक करें',
 'The commission is automatically deducted from the order value before the remaining amount is settled with the vendor or service provider.' => 'विक्रेता या सेवा प्रदाता के साथ शेष राशि का निपटान करने से पहले कमीशन स्वचालित रूप से ऑर्डर मूल्य से काट लिया जाता है।',
 'The company name often serves as the primary identifier for your business as a legal entity.' => 'कंपनी का नाम अक्सर कानूनी इकाई के रूप में आपके व्यवसाय के लिए प्राथमिक पहचानकर्ता के रूप में कार्य करता है।',
 'The cover image is required' => 'कवर छवि आवश्यक है',
 'The custom endpoint for your s3-compatible storage (optional for aws s3).' => 'आपके s3-संगत स्टोरेज के लिए कस्टम एंडपॉइंट (aws s3 के लिए वैकल्पिक)।',
 'The customer who used referral code will get discount when a place their first order.' => 'रेफरल कोड का उपयोग करने वाले ग्राहक को अपना पहला ऑर्डर देने पर छूट मिलेगी।',
 'The discount amount value must be gather than 0' => 'छूट राशि का मान 0 से अधिक होना चाहिए',
 'The discount percent value must be gather than 0' => 'छूट प्रतिशत मान 0 से अधिक होना चाहिए',
 'The execution time of a cron job is defined by the schedule when the job will be done.' => 'क्रॉन जॉब का निष्पादन समय उस शेड्यूल द्वारा परिभाषित किया जाता है जब कार्य पूरा किया जाएगा।',
 'The fav icon helps users quickly identify the site among multiple open tabs.' => 'पसंदीदा आइकन उपयोगकर्ताओं को कई खुले टैब के बीच साइट को तुरंत पहचानने में मदद करता है।',
 'The minimum number of points a customer must have before converting them into wallet money.' => 'वॉलेट मनी में परिवर्तित करने से पहले ग्राहक के पास न्यूनतम अंक होने चाहिए।',
 'The name of the s3 bucket where your files will be stored.' => 'S3 बकेट का नाम जहां आपकी फ़ाइलें संग्रहीत की जाएंगी।',
 'The option you select customer will have the option to login customer app and websites' => 'आप जो विकल्प ग्राहक चुनेंगे उसमें ग्राहक ऐप और वेबसाइटों पर लॉगइन करने का विकल्प होगा',
 'The option you select customer will have the to option to login' => 'आप जिस विकल्प का चयन करेंगे ग्राहक के पास लॉगइन करने का विकल्प होगा',
 'The option you select customers will be able to log in to both the app and website based on the option you select.' => 'आप जो विकल्प चुनेंगे ग्राहक आपके द्वारा चुने गए विकल्प के आधार पर ऐप और वेबसाइट दोनों में लॉग इन कर पाएंगे।',
 'The option you select from below will need to verify by customer from customer app/website' => 'नीचे से आपके द्वारा चुने गए विकल्प को ग्राहक द्वारा ग्राहक ऐप/वेबसाइट से सत्यापित करना होगा',
 'The private key paired with your access key for secure authentication.' => 'सुरक्षित प्रमाणीकरण के लिए निजी कुंजी को आपकी एक्सेस कुंजी के साथ जोड़ा गया है।',
 'The profile image is required' => 'प्रोफ़ाइल छवि आवश्यक है',
 'The remaining content will not be translated.' => 'शेष सामग्री का अनुवाद नहीं किया जाएगा.',
 'The remaining count updates automatically as you use services. And an option to change, renew, or change the subscription plan' => 'जैसे ही आप सेवाओं का उपयोग करते हैं, शेष गिनती स्वचालित रूप से अपडेट हो जाती है। और सदस्यता योजना को बदलने, नवीनीकृत करने या बदलने का विकल्प',
 'The service availability option has been turned off. You will not receive any new booking requests until you turn on the service availability option' => 'सेवा उपलब्धता विकल्प बंद कर दिया गया है. जब तक आप सेवा उपलब्धता विकल्प चालू नहीं करेंगे तब तक आपको कोई नया बुकिंग अनुरोध प्राप्त नहीं होगा',
 'The service availability option has been turned off. You will not receive any new customized requests until you turn on the service availability option' => 'सेवा उपलब्धता विकल्प बंद कर दिया गया है. जब तक आप सेवा उपलब्धता विकल्प चालू नहीं करते, आपको कोई नया अनुकूलित अनुरोध प्राप्त नहीं होगा',
 'The title of a Cron Job refers to the command that will be automatically executed at specific time intervals or dates when scheduled.' => 'क्रॉन जॉब का शीर्षक उस कमांड को संदर्भित करता है जो निर्धारित होने पर विशिष्ट समय अंतराल या तिथियों पर स्वचालित रूप से निष्पादित किया जाएगा।',
 'The uploaded file must be an image.' => 'अपलोड की गई फ़ाइल एक छवि होनी चाहिए.',
 'Your account username' => 'आपके खाते का उपयोगकर्ता नाम',
 'The video attachment is required' => 'वीडियो अनुलग्नक आवश्यक है',
 'The wallet reward a customer receives for each successful referral when the invited user places their first order.' => 'जब आमंत्रित उपयोगकर्ता अपना पहला ऑर्डर देता है तो प्रत्येक सफल रेफरल के लिए ग्राहक को वॉलेट इनाम मिलता है।',
 'The zip extension is not enabled' => 'ज़िप एक्सटेंशन सक्षम नहीं है',
 'Theme Mode' => 'थीम मोड',
 'Then activate the Addon and set up all the options.' => 'फिर ऐडऑन को सक्रिय करें और सभी विकल्प सेट करें।',
 'There is no advertisement created by provider yet!' => 'प्रदाता द्वारा अभी तक कोई विज्ञापन नहीं बनाया गया है!',
 'These information will be used to create super admin credential for your admin panel.' => 'इन जानकारी का उपयोग आपके एडमिन पैनल के लिए सुपर एडमिन क्रेडेंशियल बनाने के लिए किया जाएगा।',
 'They will no longer be able to combine wallet balance with other payment options.' => 'वे अब वॉलेट बैलेंस को अन्य भुगतान विकल्पों के साथ संयोजित नहीं कर पाएंगे।',
 'This Month' => 'इस महीने',
 'This SMS gateway will work for :otp_verification or :notification through SMS.' => 'यह एसएमएस गेटवे एसएमएस के माध्यम से :otp सत्यापन या :notification के लिए काम करेगा।',
 'This Year' => 'इस साल',
 'This action will replace the current database with the selected backup.' => 'यह क्रिया वर्तमान डेटाबेस को चयनित बैकअप से बदल देगी।',
 'This action will replace the current database with the selected backup. Any unsaved changes made after the backup date will be lost.' => 'यह क्रिया वर्तमान डेटाबेस को चयनित बैकअप से बदल देगी। बैकअप तिथि के बाद किए गए कोई भी सहेजे न गए परिवर्तन नष्ट हो जाएंगे।',
 'This ad is running, To delete this ad from the list, please change its status first. Once the status is updated, you can proceed with deletion' => 'यह विज्ञापन चल रहा है, इस विज्ञापन को सूची से हटाने के लिए, कृपया पहले इसकी स्थिति बदलें। एक बार स्थिति अपडेट हो जाने पर, आप हटाने के लिए आगे बढ़ सकते हैं',
 'This ad will be pause and not show in the app or web' => 'यह विज्ञापन रोक दिया जाएगा और ऐप या वेब पर नहीं दिखाया जाएगा',
 'This ad will be run again and will show in the app or web' => 'यह विज्ञापन दोबारा चलाया जाएगा और ऐप या वेब पर दिखाया जाएगा',
 'This address represents the business location from which the admin operates and manages providers, customers, and service personnel.' => 'यह पता उस व्यावसायिक स्थान का प्रतिनिधित्व करता है जहां से व्यवस्थापक प्रदाताओं, ग्राहकों और सेवा कर्मियों का संचालन और प्रबंधन करता है।',
 'This address represents the service location from which, as a provider, you operate and manage customers, services, and service personnel.' => 'यह पता उस सेवा स्थान का प्रतिनिधित्व करता है जहां से, एक प्रदाता के रूप में, आप ग्राहकों, सेवाओं और सेवा कर्मियों का संचालन और प्रबंधन करते हैं।',
 'This booking request includes custom instruction by the customer. Please read all the detailed requirements before accepting the request' => 'इस बुकिंग अनुरोध में ग्राहक द्वारा कस्टम निर्देश शामिल हैं। अनुरोध स्वीकार करने से पहले कृपया सभी विस्तृत आवश्यकताएँ पढ़ें',
 'This booking verification list is for verifying bookings whose total amount exceeds the maximum booking amount for cash on delivery' => 'यह बुकिंग सत्यापन सूची उन बुकिंग को सत्यापित करने के लिए है जिनकी कुल राशि कैश ऑन डिलीवरी के लिए अधिकतम बुकिंग राशि से अधिक है',
 'This button is now disable to active setup & turned on any sms gateway.' => 'यह बटन अब सक्रिय सेटअप के लिए अक्षम हो गया है और किसी भी एसएमएस गेटवे को चालू कर दिया गया है।',
 'This can improve flexibility and increase successful order completions.' => 'इससे लचीलेपन में सुधार हो सकता है और सफल ऑर्डर पूर्णताएं बढ़ सकती हैं।',
 'This category is available in (:zones) zones. And available subcategories (:subcategories)' => 'यह श्रेणी (:zones) क्षेत्रों में उपलब्ध है। और उपलब्ध उपश्रेणियाँ (:subcategories)',
 'This category is not under any zone. Kindly update the category with zone' => 'यह श्रेणी किसी जोन के अंतर्गत नहीं है. कृपया श्रेणी को जोन के साथ अद्यतन करें',
 'This currency is not supported by any of your current active digital payment gateways. Customer will not see the digital payment option & will not be able to pay digitally from website and apps' => 'यह मुद्रा आपके किसी भी वर्तमान सक्रिय डिजिटल भुगतान गेटवे द्वारा समर्थित नहीं है। ग्राहक को डिजिटल भुगतान विकल्प नहीं दिखेगा और वह वेबसाइट और ऐप्स से डिजिटल भुगतान नहीं कर पाएगा',
 'This field is required.' => 'यह फ़ील्ड आवश्यक है.',
 'This gives providers more options to join the business for growth and success.' => 'यह प्रदाताओं को विकास और सफलता के लिए व्यवसाय में शामिल होने के लिए अधिक विकल्प देता है।',
 'This helps to keep your new password secure.' => 'यह आपके नए पासवर्ड को सुरक्षित रखने में मदद करता है।',
 'This info will need for employee’s future login' => 'कर्मचारी के भविष्य में लॉगिन के लिए इस जानकारी की आवश्यकता होगी',
 'This is a repeat booking.' => 'यह रिपीट बुकिंग है.',
 'This is a short message shown on the website to let visitors know that the site uses cookies to collect information and improve their browsing experience' => 'यह वेबसाइट पर दिखाया गया एक छोटा संदेश है जिससे आगंतुकों को पता चलता है कि साइट जानकारी एकत्र करने और उनके ब्राउज़िंग अनुभव को बेहतर बनाने के लिए कुकीज़ का उपयोग करती है',
 'This is a short statement that shows your company owns the content on your website.' => 'यह एक संक्षिप्त विवरण है जो दिखाता है कि आपकी कंपनी आपकी वेबसाइट की सामग्री का मालिक है।',
 'This is how customer will see in the app' => 'ग्राहक को ऐप में ऐसा दिखेगा',
 'This logo is the main visual identity of the business.' => 'यह लोगो व्यवसाय की मुख्य दृश्य पहचान है।',
 'This page shows your current subscription details, billing status, and available features.' => 'यह पृष्ठ आपकी वर्तमान सदस्यता विवरण, बिलिंग स्थिति और उपलब्ध सुविधाएँ दिखाता है।',
 'This request is with customized instructions. Please read the customer description and instructions thoroughly and place your pricing according to this' => 'यह अनुरोध अनुकूलित निर्देशों के साथ है। कृपया ग्राहक विवरण और निर्देशों को अच्छी तरह से पढ़ें और इसके अनुसार अपना मूल्य निर्धारित करें',
 'This requires SMS Gateway setup to be configured first.' => 'इसके लिए पहले एसएमएस गेटवे सेटअप को कॉन्फ़िगर करना आवश्यक है।',
 'This section allows you to configure SMTP email settings so the system can send emails reliably.' => 'यह अनुभाग आपको एसएमटीपी ईमेल सेटिंग्स कॉन्फ़िगर करने की अनुमति देता है ताकि सिस्टम विश्वसनीय रूप से ईमेल भेज सके।',
 'This section allows you to configure basic settings for your services.' => 'यह अनुभाग आपको अपनी सेवाओं के लिए बुनियादी सेटिंग्स कॉन्फ़िगर करने की अनुमति देता है।',
 'This section currently includes Time Zone and Date Format, Pagination Limit, Phone Number Visibility in Chat, and Currency configuration.' => 'इस अनुभाग में वर्तमान में समय क्षेत्र और दिनांक प्रारूप, पृष्ठांकन सीमा, चैट में फ़ोन नंबर दृश्यता और मुद्रा कॉन्फ़िगरेशन शामिल हैं।',
 'This section is used to configure Google Map integration for your system.' => 'इस अनुभाग का उपयोग आपके सिस्टम के लिए Google मानचित्र एकीकरण को कॉन्फ़िगर करने के लिए किया जाता है।',
 'This section may help user to get the update features in their app.' => 'यह अनुभाग उपयोगकर्ता को अपने ऐप में अद्यतन सुविधाएँ प्राप्त करने में मदद कर सकता है।',
 'This setup connects your application with your Firebase project using official credentials provided by Google.' => 'यह सेटअप Google द्वारा प्रदान किए गए आधिकारिक क्रेडेंशियल्स का उपयोग करके आपके एप्लिकेशन को आपके फायरबेस प्रोजेक्ट से जोड़ता है।',
 'This social media link has already been added. Please choose a different platform or update the existing one' => 'यह सोशल मीडिया लिंक पहले ही जोड़ा जा चुका है। कृपया एक अलग प्लेटफ़ॉर्म चुनें या मौजूदा को अपडेट करें',
 'This view is from the user app.' => 'यह दृश्य उपयोगकर्ता ऐप से है.',
 'This view is from the user app. This is how customer will see in the app' => 'यह दृश्य उपयोगकर्ता ऐप से है. ग्राहक को ऐप में ऐसा दिखेगा',
