 'To' => 'को',
 'To Integrate add-on to your system please follow the instruction below' => 'अपने सिस्टम में ऐड-ऑन एकीकृत करने के लिए कृपया नीचे दिए गए निर्देशों का पालन करें',
 'To activate the subscription-based business model, first add a subscription package from :subscription_packages_link.' => 'सदस्यता-आधारित व्यवसाय मॉडल को सक्रिय करने के लिए, पहले :subscription पैकेज लिंक से एक सदस्यता पैकेज जोड़ें।',
 'To change currency setup, visit' => 'मुद्रा सेटअप बदलने के लिए, पर जाएँ',
 'To change currency setup, visit the :business_information_link page.' => 'मुद्रा सेटअप बदलने के लिए, :business सूचना लिंक पृष्ठ पर जाएँ।',
 'To configure OTP in Firebase, you must create a Firebase project first.' => 'फायरबेस में ओटीपी को कॉन्फ़िगर करने के लिए, आपको पहले एक फायरबेस प्रोजेक्ट बनाना होगा।',
 'To continue using :business_name, please choose a paid business plan.' => ':business नाम का उपयोग जारी रखने के लिए, कृपया एक सशुल्क व्यवसाय योजना चुनें।',
 'To enable Email verification, please set up the Email configuration and turn on the status first.' => 'ईमेल सत्यापन सक्षम करने के लिए, कृपया ईमेल कॉन्फ़िगरेशन सेट करें और पहले स्थिति चालू करें।',
 'To enable Phone verification, please set up the SMS configuration and turn on the status first.' => 'फ़ोन सत्यापन सक्षम करने के लिए, कृपया एसएमएस कॉन्फ़िगरेशन सेट करें और पहले स्थिति चालू करें।',
 'To enable map-based features such as location selection, serviceman tracking, and distance calculation, you must provide valid Google Map API keys.' => 'स्थान चयन, सर्विसमैन ट्रैकिंग और दूरी गणना जैसी मानचित्र-आधारित सुविधाओं को सक्षम करने के लिए, आपको मान्य Google मानचित्र API कुंजियाँ प्रदान करनी होंगी।',
 'To enable the Apple ID Login option, please set up the Apple ID configuration first.' => 'Apple ID लॉगिन विकल्प को सक्षम करने के लिए, कृपया पहले Apple ID कॉन्फ़िगरेशन सेट करें।',
 'To enable the Apple login system, please set up the Apple configuration first.' => 'Apple लॉगिन सिस्टम को सक्षम करने के लिए, कृपया पहले Apple कॉन्फ़िगरेशन सेट करें।',
 'To enable the Facebook Login option, please set up the Facebook configuration first.' => 'फेसबुक लॉगिन विकल्प को सक्षम करने के लिए, कृपया पहले फेसबुक कॉन्फ़िगरेशन सेट करें।',
 'To enable the OTP system, please set up the Google configuration first.' => 'ओटीपी प्रणाली को सक्षम करने के लिए, कृपया पहले Google कॉन्फ़िगरेशन सेट करें।',
 'To enable the OTP system, please set up the SMS configuration first.' => 'ओटीपी प्रणाली को सक्षम करने के लिए, कृपया पहले एसएमएस कॉन्फ़िगरेशन सेट करें।',
 'To enable the social media login system, please set up the social media configuration first.' => 'सोशल मीडिया लॉगिन सिस्टम को सक्षम करने के लिए, कृपया पहले सोशल मीडिया कॉन्फ़िगरेशन सेट करें।',
 'To enable this feature must be activated' => 'इस सुविधा को सक्षम करने के लिए सक्रिय होना होगा',
 'To enable this feature, you have to activate social media from the Social media login setup option below.' => 'इस सुविधा को सक्षम करने के लिए, आपको नीचे दिए गए सोशल मीडिया लॉगिन सेटअप विकल्प से सोशल मीडिया को सक्रिय करना होगा।',
 'To finalize the process and make payment arrangements, please contact our' => 'प्रक्रिया को अंतिम रूप देने और भुगतान की व्यवस्था करने के लिए कृपया हमसे संपर्क करें',
 'To get site key and secret key Go to the Credentials page' => 'साइट कुंजी और गुप्त कुंजी प्राप्त करने के लिए क्रेडेंशियल पृष्ठ पर जाएं',
 'To get site key and secret keyGo to the Credentials page' => 'साइट कुंजी और गुप्त कुंजी प्राप्त करने के लिए क्रेडेंशियल पृष्ठ पर जाएं',
 'To make these payment options available, you must enable the Digital payment option from the :business_information_link page.' => 'इन भुगतान विकल्पों को उपलब्ध कराने के लिए, आपको :business सूचना लिंक पृष्ठ से डिजिटल भुगतान विकल्प को सक्षम करना होगा।',
 'To make these payment options available, you must enable the Offline payment option from the :business_information_link page.' => 'इन भुगतान विकल्पों को उपलब्ध कराने के लिए, आपको :business सूचना लिंक पृष्ठ से ऑफ़लाइन भुगतान विकल्प को सक्षम करना होगा।',
 'To renew your subscription & maintain uninterrupted service, please follow the link below' => 'अपनी सदस्यता नवीनीकृत करने और निर्बाध सेवा बनाए रखने के लिए कृपया नीचे दिए गए लिंक का अनुसरण करें',
