 'You can also allow automatic account creation using guest information to convert guests into registered users.' => 'आप मेहमानों को पंजीकृत उपयोगकर्ताओं में बदलने के लिए अतिथि जानकारी का उपयोग करके स्वचालित खाता निर्माण की अनुमति भी दे सकते हैं।',
 'You can also mark a method as default, update its information, or remove it if necessary.' => 'आप किसी विधि को डिफ़ॉल्ट के रूप में भी चिह्नित कर सकते हैं, उसकी जानकारी अपडेट कर सकते हैं, या यदि आवश्यक हो तो उसे हटा सकते हैं।',
 'You can create an ad on behalf of a provider.' => 'आप किसी प्रदाता की ओर से एक विज्ञापन बना सकते हैं.',
 'You can force the customer from here by providing the minimum version for force update.' => 'आप बलपूर्वक अद्यतन के लिए न्यूनतम संस्करण प्रदान करके ग्राहक को यहां से बाध्य कर सकते हैं।',
 'You can force the user from here by providing the minimum version for force update.' => 'आप फोर्स अपडेट के लिए न्यूनतम संस्करण प्रदान करके उपयोगकर्ता को यहां से मजबूर कर सकते हैं।',
 'You can get the PHP file path from your server. Here is an example of Apache Server -' => 'आप अपने सर्वर से PHP फ़ाइल पथ प्राप्त कर सकते हैं। यहां अपाचे सर्वर का एक उदाहरण दिया गया है -',
 'You can manage all your storage files from' => 'आप अपनी सभी संग्रहण फ़ाइलों को यहां से प्रबंधित कर सकते हैं',
 'You can manage your campaign discount from :campaign_discount_link.' => 'आप अपने अभियान छूट को :campaign डिस्काउंट लिंक से प्रबंधित कर सकते हैं।',
 'You can manage your coupon discount from :coupon_discount_link.' => 'आप अपने कूपन छूट को :coupon डिस्काउंट लिंक से प्रबंधित कर सकते हैं।',
 'You can manage your normal discount from :normal_discount_link.' => 'आप अपनी सामान्य छूट को :normal डिस्काउंट लिंक से प्रबंधित कर सकते हैं।',
 'You can not consume your subscription after :date' => 'आप :date के बाद अपनी सदस्यता का उपभोग नहीं कर सकते',
 'You can not turn off the SMS configuration status since the Phone verification status is active in login setup' => 'आप एसएमएस कॉन्फ़िगरेशन स्थिति को बंद नहीं कर सकते क्योंकि फ़ोन सत्यापन स्थिति लॉगिन सेटअप में सक्रिय है',
 'You can not turn off the email configuration status since the Email verification status is active in login setup' => 'आप ईमेल कॉन्फ़िगरेशन स्थिति को बंद नहीं कर सकते क्योंकि ईमेल सत्यापन स्थिति लॉगिन सेटअप में सक्रिय है',
 'You can not undo this after deleting this logs' => 'आप इस लॉग को हटाने के बाद इसे पूर्ववत नहीं कर सकते',
 'You can now access your account & reset your password from our app & website.' => 'अब आप हमारे ऐप और वेबसाइट से अपने खाते तक पहुंच सकते हैं और अपना पासवर्ड रीसेट कर सकते हैं।',
 'You can offer providers a free trial to experience the system overall.' => 'आप सिस्टम का समग्र अनुभव लेने के लिए प्रदाताओं को निःशुल्क परीक्षण की पेशकश कर सकते हैं।',
 'You can only add up to 10 custom pages.' => 'आप केवल 10 कस्टम पेज तक जोड़ सकते हैं.',
 'You can see all inactive suspended providers on the :provider_list_link page.' => 'आप सभी निष्क्रिय निलंबित प्रदाताओं को :provider सूची लिंक पृष्ठ पर देख सकते हैं।',
 'You can see all providers service man list from this' => 'आप यहां से सभी प्रोवाइडर सर्विस मैन लिस्ट देख सकते हैं',
 'You can see status wise advertisement history and adjust edit, pause, resume, resubmit, or delete as needed.' => 'आप स्थिति के अनुसार विज्ञापन इतिहास देख सकते हैं और आवश्यकतानुसार संपादन, रोकें, फिर से शुरू, पुनः सबमिट या हटा सकते हैं।',
 'You can see status wise advertisement history and adjust priority.' => 'आप स्थिति के अनुसार विज्ञापन इतिहास देख सकते हैं और प्राथमिकता समायोजित कर सकते हैं।',
 'You can use any of our secure payment method & get selected subscription plan features' => 'आप हमारी किसी भी सुरक्षित भुगतान पद्धति का उपयोग कर सकते हैं और चयनित सदस्यता योजना सुविधाएँ प्राप्त कर सकते हैं',
 'You can use the same API for both fields without any restrictions.' => 'आप बिना किसी प्रतिबंध के दोनों क्षेत्रों के लिए एक ही एपीआई का उपयोग कर सकते हैं।',
 'You can withdraw this amount from Admin, as you have more receivable balance than cash in hand.' => 'आप इस राशि को एडमिन से निकाल सकते हैं, क्योंकि आपके पास हाथ में नकदी की तुलना में प्राप्य शेष अधिक है।',
 'You can withdraw this amount from the Admin.' => 'आप इस राशि को एडमिन से निकाल सकते हैं।',
 'You cannot activate both storage connection statuses at the same time. You must activate at least one status' => 'आप एक ही समय में दोनों संग्रहण कनेक्शन स्थितियों को सक्रिय नहीं कर सकते। आपको कम से कम एक स्टेटस सक्रिय करना होगा',
 'You cannot change your own role status' => 'आप अपनी भूमिका की स्थिति नहीं बदल सकते',
 'You cannot change your own status' => 'आप अपनी स्थिति नहीं बदल सकते',
 'You cannot delete your own profile' => 'आप अपनी स्वयं की प्रोफ़ाइल नहीं हटा सकते',
 'You cannot delete your own role' => 'आप अपनी स्वयं की भूमिका नहीं हटा सकते',
 'You cannot edit your own role' => 'आप अपनी स्वयं की भूमिका संपादित नहीं कर सकते',
 'You cannot modify your own permissions.' => 'आप अपनी स्वयं की अनुमतियाँ संशोधित नहीं कर सकते.',
 'You cannot modify your own role' => 'आप अपनी स्वयं की भूमिका को संशोधित नहीं कर सकते',
 'You cannot set permissions on your own profile' => 'आप अपनी प्रोफ़ाइल पर अनुमतियाँ सेट नहीं कर सकते',
 'You cannot undo this after deleting the selected logs.' => 'चयनित लॉग को हटाने के बाद आप इसे पूर्ववत नहीं कर सकते।',
 'You can’t delete the ad' => 'आप विज्ञापन नहीं हटा सकते',
 'You did not create any advertisement yet!' => 'आपने अभी तक कोई विज्ञापन नहीं बनाया!',
 'You don’t have any reviews yet.' => 'आपके पास अभी तक कोई समीक्षा नहीं है.',
 'You have Earned a Referral Reward!' => 'आपने एक रेफरल पुरस्कार अर्जित किया है!',
 'You have Earned a Reward!' => 'आपने पुरस्कार अर्जित किया है!',
 'You have cash in hand, you have to pay the due to delete your account.' => 'आपके पास नकदी है, आपको अपना खाता हटाने के लिए देय राशि का भुगतान करना होगा।',
 'You have earned a reward for referring a new user, who has now completed their first booking using your code...' => 'आपने एक नए उपयोगकर्ता को रेफ़र करने के लिए पुरस्कार अर्जित किया है, जिसने अब आपके कोड का उपयोग करके अपनी पहली बुकिंग पूरी कर ली है...',
 'You have earned a reward for sign up with a referral code and first booking...' => 'आपने रेफरल कोड और पहली बुकिंग के साथ साइन अप करने के लिए पुरस्कार अर्जित किया है...',
 'You have the option to either switch all providers plans or allow providers to make changes.' => 'आपके पास या तो सभी प्रदाता योजनाओं को बदलने या प्रदाताओं को परिवर्तन करने की अनुमति देने का विकल्प है।',
 'You have to give a certain percentage of commission to admin for every booking request' => 'आपको प्रत्येक बुकिंग अनुरोध के लिए एडमिन को कमीशन का एक निश्चित प्रतिशत देना होगा',
 'You have to pay a certain amount in every month / year to admin as subscription fee' => 'आपको सदस्यता शुल्क के रूप में एडमिन को हर महीने/वर्ष में एक निश्चित राशि का भुगतान करना होगा',
 'You have to pay this amount to Admin, as you have more cash in hand balance than receivable balance' => 'आपको यह राशि एडमिन को चुकानी होगी, क्योंकि आपके पास प्राप्य शेष से अधिक नकद शेष है',
 'You have to pay this amount to the Admin. As after adjusting the both receivable and cash in hand balance, you have more cash in hand balance than receivable balance' => 'यह रकम आपको एडमिन को देनी होगी. चूंकि प्राप्य और नकदी शेष दोनों को समायोजित करने के बाद, आपके पास प्राप्य शेष की तुलना में हाथ में नकदी शेष अधिक है',
 'You have to setup a SMS module from below fist to active this feature' => 'इस सुविधा को सक्रिय करने के लिए आपको मुट्ठी के नीचे से एक एसएमएस मॉड्यूल सेटअप करना होगा',
 'You have to verify the booking because of maximum amount exceed' => 'अधिकतम राशि अधिक होने के कारण आपको बुकिंग सत्यापित करनी होगी',
 'You have uploaded a wrong format file, please upload the right file.' => 'आपने गलत प्रारूप वाली फ़ाइल अपलोड की है, कृपया सही फ़ाइल अपलोड करें।',
 'You haven’t any conversation yet' => 'आपने अभी तक कोई बातचीत नहीं की है',
 'You must activate at least one digital payment method that supports your system currency (:currency).' => 'आपको कम से कम एक डिजिटल भुगतान विधि सक्रिय करनी होगी जो आपके सिस्टम मुद्रा (:currency) का समर्थन करती हो।',
 'You must select at least one system when activating Maintenance Mode.' => 'रखरखाव मोड सक्रिय करते समय आपको कम से कम एक सिस्टम का चयन करना होगा।',
 'You must set up :firebase_configuration to make notifications work.' => 'सूचनाओं को कार्यशील बनाने के लिए आपको :firebase कॉन्फ़िगरेशन सेट करना होगा।',
 'You must setup for V3 version. Otherwise the default reCAPTCHA will be displayed automatically' => 'आपको V3 संस्करण के लिए सेटअप करना होगा. अन्यथा डिफ़ॉल्ट reCAPTCHA स्वचालित रूप से प्रदर्शित किया जाएगा',
 'You must update your location first' => 'आपको पहले अपना स्थान अपडेट करना होगा',
 'You need to go to the Customer Location to provide the service' => 'सेवा प्रदान करने के लिए आपको ग्राहक स्थान पर जाना होगा',
 'You now have access to all the premium features included in your selected plan.' => 'अब आपके पास आपके चयनित प्लान में शामिल सभी प्रीमियम सुविधाओं तक पहुंच है।',
 'You offer will be removed for the post' => 'पोस्ट के लिए आपका ऑफर हटा दिया जाएगा',
 'You want to Turn Off the Push Notification Status' => 'आप पुश अधिसूचना स्थिति को बंद करना चाहते हैं',
 'You want to Turn On the Push Notification Status' => 'आप पुश अधिसूचना स्थिति को चालू करना चाहते हैं',
 'You want to turn Off the social media status' => 'आप सोशल मीडिया स्टेटस को बंद करना चाहते हैं',
 'You want to turn On this social media status' => 'आप इस सोशल मीडिया स्टेटस को चालू करना चाहते हैं',
