 'You_have_to_pay_a_certain_amount_in_every_month_/_year_to_admin_as_subscription_fee' => 'आपको सदस्यता शुल्क के रूप में एडमिन को हर महीने/वर्ष में एक निश्चित राशि का भुगतान करना होगा',
 'Your Commission To Subscription has been shifted successfully!' => 'सदस्यता के लिए आपका कमीशन सफलतापूर्वक स्थानांतरित कर दिया गया है!',
